let NETDOWN=0;const netDown=()=>navigator.onLine===false||Date.now()-NETDOWN<5000;
async function getJSON(p){let r;try{r=await fetch(p,{cache:'no-cache'})}catch(e){NETDOWN=Date.now();throw e}if(!r.ok)throw new Error(r.status);return r.json()}
async function loadSite(){if(S.site)return S.site;try{S.site=await getJSON('/content/site.json')}catch(e){S.site={name:'PawPixl',tagline:'',socials:[],games:[{id:'genshin',name:'Genshin Impact',status:'live',el:'Hydro'}]}}return S.site}
/* Guide data comes in three sizes, all written by PawPixl Studio in the same save:
   - index-lite.json : every guide's name, element, date and picture. Enough for the home page, search, lists and links.
   - g/<character>.json : one complete guide. Loaded when that guide (or its materials page) is opened.
   - index.json : everything at once, as before. Loaded only by the tools that compare many guides (the Labs, My Roster,
     For You, the farming planner), and used for everything on a website published before the lighter files existed. */
const FULLG=new Set(),FULLB=new Set(),LG={},LGF={};
function loadGame(id){if(S.games[id])return Promise.resolve(S.games[id]);if(LG[id])return LG[id];
 LG[id]=(async()=>{let g=null;try{g=await getJSON('/content/'+id+'/index-lite.json');if(!g||!g.lite||!g.posts)g=null}catch(e){g=null}
  if(!g){try{g=await getJSON('/content/'+id+'/index.json');FULLG.add(id)}catch(e){g={roster:[],posts:{}}}}
  g.posts=g.posts||{};S.games[id]=g;delete LG[id];return g})();return LG[id]}
const buildFull=(id,key)=>FULLG.has(id)||FULLB.has(id+'/'+key);
/* the complete library: swapped into the same object, so everything already on screen keeps working */
async function loadGameFull(id){const g=await loadGame(id);if(FULLG.has(id))return g;
 if(!LGF[id])LGF[id]=getJSON('/content/'+id+'/index.json').then(f=>{if(f&&f.posts&&f.posts.builds){g.posts=f.posts;g.roster=f.roster||g.roster;g.updated=f.updated;delete g.lite;FULLG.add(id)}delete LGF[id];return g}).catch(e=>{delete LGF[id];return g});
 return LGF[id]}
/* index-tools.json: everything the tools compare across guides (weapons, artifacts, stats, teams, the reasons for each
   pick, materials, talents) with the cards left out. Guides already opened in full are kept as they are. If the file is
   not there (a website from before it existed), the complete library is loaded instead, exactly as before. */
const TOOLG=new Set(),LGT={};
async function loadGameTools(id){const g=await loadGame(id);if(FULLG.has(id)||TOOLG.has(id))return g;
 if(!LGT[id])LGT[id]=getJSON('/content/'+id+'/index-tools.json').then(f=>{if(!f||!f.tools||!f.posts||!f.posts.builds)throw new Error('tools');if(FULLG.has(id))return g;
   const B=g.posts.builds=g.posts.builds||{},T=f.posts.builds;Object.keys(T).forEach(k=>{if(!FULLB.has(id+'/'+k))B[k]=T[k]});Object.keys(B).forEach(k=>{if(!T[k])delete B[k]});
   if(f.roster)g.roster=f.roster;g.updated=f.updated;TOOLG.add(id);delete LGT[id];return g}).catch(e=>{delete LGT[id];return loadGameFull(id)});
 return LGT[id]}
/* one complete guide; if its own file is not there (a website from before the split), the complete library instead */
