function parseTime(s){const m=/^(\d{1,2})(?::(\d{2}))?\s*(am|pm|a|p)?/i.exec(String(s||'').trim());if(!m)return null;let h=+m[1];if(m[3]){h%=12;if(/^p/i.test(m[3]))h+=12}return{h,mi:+(m[2]||0)}}
