 for(const sp of SP){if(sp.kind==='off')continue;const has=(D.rows||[]).some(r=>r.d===sp.d&&r.on&&r.time&&(r.game||r.desc));if(sp.kind==='extra'||!has)add(sp.d,sp.time,'',sp.what||'Stream',sp.hrs)}
