function pPrivacy(){nav(null);meta('Privacy');return'<section class="prose"><div class="eyebrow">Privacy</div><h2 class="disp" style="font-size:44px;margin:10px 0 14px">Your privacy</h2><p>You can browse and download everything here without an account.</p><p>If you sign in, the site stores only your account email (or the Discord/Google account you chose), your favorites and the time you last checked for new posts, so it can show you what’s new. Nothing is sold or shared.</p><p>Weapons you mark as owned and your My Roster (the characters you own, constellations, levels, talents, weapons and notes) are saved the same way: in your account if you’re signed in, otherwise only in this browser. Only you can see them.</p><p>Accounts are for players 13 and older. On the Account page you can download everything saved, sign out on every device, or delete your account, which removes your sign-in and everything saved with it.</p><p>Your language choice and last visit are also kept in your browser. You can delete your saved favorites and account data any time from the Account page.</p><p>Visitor numbers are counted without cookies, as daily totals only: which country and region visits come from, the language, the kind of device and browser, the site that linked here, which pages were viewed and at what hour. So nobody is counted twice, your browser keeps a few small markers (dates, not an ID): whether you’ve visited before, when you were last active and the day you were last counted. No IP addresses, names or anything that identifies you are stored, and nothing is shared with advertisers.</p><p>So the site opens quickly and still works with no signal, your browser keeps a copy of pages and pictures you’ve opened recently on this device. If you add PawPixl to your home screen, it uses that same copy. It never leaves your device, and clearing your browser’s site data removes it.</p>'+(supOn()||picksItems().length?'<p>The same daily totals count how many visits used the support link'+(picksItems().length?' or opened an item on '+esc(picksTitle()):'')+'. They never record who clicked, and a click is all that is counted: nothing about donations or purchases comes back to this site.</p>':'')+(picksItems().length?'<p>Some links on '+esc(picksTitle())+' are affiliate links (for example Amazon). If you buy through them, I may earn a small commission at no extra cost to you. Those shops have their own privacy policies.</p>':'')+'</section>'}

/* ---------- fan accounts (optional) ---------- */
/* a sign-in link that has expired or was already used comes back with the reason in the address (#error_code=otp_expired):
   keep it to explain on the Account page, and clear it from the address bar */
function authLinkError(){try{const h=new URLSearchParams(location.hash.replace(/^#/,'')),q=new URLSearchParams(location.search);const code=h.get('error_code')||q.get('error_code'),desc=h.get('error_description')||q.get('error_description');if(!code&&!desc)return;
 S.authErr=code==='otp_expired'||/expired|invalid/i.test(desc||'')?'That sign-in link has expired or was already used. Each link works once, on any device. If you asked for another link after this one, only the newest email works. Send yourself a new link below.':code==='access_denied'||/access_denied|denied|cancel/i.test(desc||'')?'Sign-in was cancelled before it finished, so nothing changed. Please try again below.':'Signing in didn’t work ('+String(desc||code).replace(/\+/g,' ').slice(0,120)+'). Please try again below.';
 history.replaceState(null,'',location.pathname+(location.search.replace(/[?&]error[^&]*/g,'').replace(/^&/,'?')))}catch(e){}}
