/* ---------- Stats check (update 14) ----------
   Three kinds of numbers, never mixed:
     imported      what the game reported in a showcase answer (row.imp), shown as it came
     reconstructed what PawPixl works out from its own database and the build in My Roster, every fight-dependent effect off
     combat        Build Lab, with the effects the visitor switches on
   The reconstruction never starts from an imported total. The two are only compared, and the allowed gap is the rounding of the
   import itself: every artifact number in a showcase answer is the rounded figure the game prints, so a percentage line can be
   off by 0.05% of the base and a flat line by 0.5. A gap larger than that is shown as open. */
const PPCD={};async function ppCharData(id){if(!PPCD[id])PPCD[id]=getJSON('/content/genshin/db/c/'+encodeURIComponent(id)+'.json').catch(e=>{delete PPCD[id];throw e});return PPCD[id]}
