 const a=d.a||null,subs={};SUBK.forEach(k=>{const v=+((a&&a.sub||{})[k])||0;subs[k]=PCT(k)?v/100:v});
 const L={cd,li,w,wli:Math.max(0,wli),ri:Math.max(0,(d.wr||1)-1),cons:d.c||0,art:!!a,mode:a&&a.mode==='22'?'22':'4',s1:(a&&a.s1)||'',s2:(a&&a.s2)||'',sands:(a&&a.sands)||'',goblet:(a&&a.goblet)||'',circlet:(a&&a.circlet)||'',subs,mv:(a&&a.mv)||null,sets:A,cw:{},c4:{},bf:null,nofx:true};
