 (cd.pa||[]).forEach(p=>{if(hit(p.d)&&!efxOf(cd.id).some(z=>z.n===p.n&&!z.when)&&!rec.also.some(z=>z[0]===p.n))out.push('Passive talent “'+p.n+'” mentions '+open.filter(k=>word[k].test(p.d)).map(k=>k==='el'?el+' DMG Bonus':STN[k]).join(', ')+' and is not counted here.')});
