 const body=CHKK.map(([k2])=>{const r=C&&C.rows.find(z=>z.k===k2),v=rec.T[k2]||0;if(!C&&!v&&['phys','heal'].includes(k2))return'';if(C&&!v&&!r.g)return'';
  return'<tr data-k="'+k2+'"'+(r?' data-st="'+r.st+'"':'')+'><td>'+esc(nm(k2))+'</td>'+(C?'<td data-imp="'+r.g+'">'+f(k2,r.g)+'</td>':'')+'<td data-rec="'+(Math.round(v*1e4)/1e4)+'"><b>'+f(k2,v)+'</b></td>'+(C?'<td class="chk-'+ST[r.st][0]+'">'+(r.st==='match'?ST.match[1]:(r.df>0?'+':'−')+(PCT(k2)?(Math.abs(r.df)*100).toFixed(1)+'%':Math.round(Math.abs(r.df)).toLocaleString())+' <small>'+ST[r.st][1]+'</small>')+'</td>':'')+'</tr>'}).join('');
 const notes=[];
 if(C&&C.stale)notes.push('You changed this build after the import, so the in-game numbers are from the earlier build. Import again to compare the two fairly.');
 if(!rec.lvExact)notes.push('Level '+x.l+' is between the levels in PawPixl’s data, so HP, ATK and DEF are worked out at level '+lvLabel(rec.row[0],rec.row[1],cd.lv)+' and will be a little lower than in the game.');
