const arenaPv=()=>{try{if(new URLSearchParams(location.search).get('preview')==='arena')sessionStorage.setItem('pp.arena.pv','1');return sessionStorage.getItem('pp.arena.pv')==='1'}catch(e){return false}};
const arenaOn=()=>!!(S.site&&S.site.arena&&S.site.arena.on)||arenaPv();
