/* visit counting v2 (18 Nov): daily totals only, no cookies and no IDs. This browser keeps a few small markers (dates, not
   IDs): whether it has been here before, when it was last active (a visit ends after 30 minutes without activity, across
   tabs), the page it was last on, and the day / week / month it was last counted. So a returning visitor is never counted as
   new, nobody is counted twice in a day, and a refresh isn't a new page view. Automated browsers aren't counted, and the
   owner's own browsers are dropped by the website before anything is written (see /api/me). */
const ETF=(()=>{try{return new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'})}catch(e){return null}})();
const etDay=()=>ETF?ETF.format(new Date()):new Date().toISOString().slice(0,10);
