 if(prev&&prev!==path){const g=isGuidePath(prev),here=isGuidePath(path);
  o.n=g?(here?'g2g':/\/lab$/.test(path)?'g2lab':/\/teamlab$/.test(path)?'g2tl':/\/roster$/.test(path)?'g2ros':/^\/account/.test(path)?'g2acct':/^\/arena/.test(path)?'g2arena':''):here?(/\/lab$/.test(prev)?'lab2g':/\/teamlab$/.test(prev)?'tl2g':''):'';if(!o.n)delete o.n}
