/* ---------- installable app (PWA) ----------
   The site can be added to a phone's home screen or a computer's apps. Nothing here interrupts anyone: there is a
   quiet "Install app" link in the footer, and one small note on the home page that is shown a single time, only after
   a few page views, and never again once it is closed or the app is installed. sw.js keeps recent guides readable
   with no signal and always takes fresh pages when there is a connection. */
const PWA={ev:null};
const pwaAlone=()=>{try{return matchMedia('(display-mode: standalone)').matches||navigator.standalone===true}catch(e){return false}};
const pwaIOS=()=>/iPhone|iPad|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
const pwaInApp=()=>/musical_ly|BytedanceWebview|TikTok|Instagram|FBAN|FBAV|Discord|Snapchat|Line\//i.test(navigator.userAgent);
const pwaCan=()=>!pwaAlone()&&(!!PWA.ev||(pwaIOS()&&!pwaInApp()));
function pwaSeen(){const n=(+store.get('pwa.n',0)||0)+1;if(n<1e4)store.set('pwa.n',n)}
/* decided once, while the home page is being built, so nothing ever pops in later and pushes the page down */
